def statuses_forward(apps, schema_editor):
    Booking = apps.get_model("booking", "Booking")
    Booking.objects.filter(status="active").update(status="confirmed")


def statuses_backward(apps, schema_editor):
    Booking = apps.get_model("booking", "Booking")
    Booking.objects.exclude(status="cancelled").update(status="active")


def prepaid_to_payments(apps, schema_editor):
    """Предоплата, записанная в броне, становится первым платежом."""
    Booking = apps.get_model("booking", "Booking")
    Payment = apps.get_model("booking", "Payment")
    tz = django.utils.timezone.get_current_timezone()
    for booking in Booking.objects.filter(prepaid__gt=0):
        Payment.objects.create(
            booking=booking,
            amount=booking.prepaid,
            kind="payment",
            method="other",
            comment="Предоплата",
            date=booking.created_at.astimezone(tz).date(),
        )


def payments_to_prepaid(apps, schema_editor):
    Booking = apps.get_model("booking", "Booking")
    for booking in Booking.objects.all():
        total = sum(p.amount if p.kind == "payment" else -p.amount for p in booking.payments.all())
        if total > 0:
            booking.prepaid = total
            booking.save(update_fields=["prepaid"])


